//! Barrel for libmtmd's port: upstream's multimodal library
//! (`llama.cpp/tools/mtmd/`), the vision and audio encoders and the audio
//! generators behind `llama-mtmd-cli` and `llama-tts`.
//!
//! **Not a port.** It gathers the files under `src/mtmd/`:
//!
//! - `names.zig` -- `clip-impl.h`'s keys, tensor names and projector types,
//!   generated by `scripts/gen-mtmd-names`
//! - `impl.zig` -- the rest of `clip-impl.h` and `clip.h`: image types,
//!   logging, utilities
//! - `model.zig` -- `clip-model.h`
//! - `graph.zig` -- `clip-graph.h` and `clip_graph`'s shared builders
//! - `clip.zig` -- `clip.cpp`: the context, the loader, encoding
//! - `arms_hparams.zig`, `arms_tensors.zig`, `arms_inputs.zig` -- `clip.cpp`'s
//!   per-projector switches
//! - `models/` -- `models/*.cpp`, the encoder graphs
//! - `image.zig` -- `mtmd-image.cpp`, the image preprocessors
//! - `audio.zig` -- `mtmd-audio.cpp`, the audio preprocessors
//! - `vendor/` -- the vendored decoders `mtmd-helper.cpp` compiles in
//! - `mtmd.zig` -- `mtmd.cpp`: the public API, tokenizing and encoding
//! - `helper.zig` -- `mtmd-helper.cpp`: loading bitmaps, evaluating chunks
//! - `helper_gen.zig` -- `mtmd-helper-gen.cpp`: the TTS pipelines

const std = @import("std");

pub const names = @import("names.zig");
pub const impl = @import("impl.zig");
pub const model = @import("model.zig");
pub const graph = @import("graph.zig");
pub const clip = @import("clip.zig");
pub const arms_hparams = @import("arms_hparams.zig");
pub const arms_tensors = @import("arms_tensors.zig");
pub const arms_inputs = @import("arms_inputs.zig");
pub const models = @import("models/module.zig");
pub const image = @import("image.zig");
pub const audio = @import("audio.zig");
pub const vendor = @import("vendor/module.zig");
pub const mtmd = @import("mtmd.zig");
pub const helper = @import("helper.zig");
pub const helper_gen = @import("helper_gen.zig");

comptime {
    // Every mtmd.h and mtmd-helper.h entry point, by name. The harnesses
    // root at harness_root.zig instead, which exports nothing.
    _ = @import("exports.zig");
}

